
$bg-color: #0a0a0d;
$glass-bg: rgba(20, 20, 25, 0.6);
$border-gold: rgba(234, 179, 8, 0.4);
$accent-gold: #eab308;
$text-main: #e4e4e7;
$text-dim: #a1a1aa;
$glow-shadow: 0 0 15px rgba(234, 179, 8, 0.15);

.trpg-status-panel {
  width: 100%;
  background: linear-gradient(180deg, #111116 0%, #08080a 100%);
  color: $text-main;
  font-family: 'Segoe UI', system-ui, sans-serif;
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 4px;
  padding: 16px;
  box-shadow: inset 0 0 30px rgba(0,0,0,0.8), 0 4px 20px rgba(0,0,0,0.5);
  backdrop-filter: blur(12px);
}

.panel-layout {
  display: flex;
  gap: 32px;
}

.left-column, .right-column {
  flex: 1;
  display: flex;
  flex-direction: column;
}

/* 分割线：黑魂风格细横线 */
.section-title {
  margin: 0 0 8px 0;
  font-size: 1rem;
  color: $text-main;
  font-weight: normal;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  padding-bottom: 4px;
  letter-spacing: 1px;
}

/* 头部样式：头像与信息组合 */
.identity-header {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);

  .avatar-box {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    border: 2px solid $accent-gold;
    box-shadow: $glow-shadow;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(0,0,0,0.5);
    flex-shrink: 0;

    .avatar-icon {
      width: 32px;
      height: 32px;
      color: $accent-gold;
    }
  }

  .identity-info {
    flex: 1;

    .char-name {
      margin: 0 0 4px 0;
      font-size: 1.5rem;
      font-weight: 600;
      color: #fff;
      letter-spacing: 2px;
      text-shadow: 0 0 10px rgba(255,255,255,0.2);
    }

    .status-line {
      font-size: 0.85rem;
      color: $text-dim;

      .status-alive {
        color: $accent-gold;
        font-family: monospace;
      }

      .separator {
        color: rgba(255,255,255,0.2);
        margin: 0 4px;
      }

      .gene-lock {
        color: #fff;
        text-shadow: 0 0 5px rgba(255,255,255,0.3);
      }
    }

    /* 血统/改造与评级 (可点击展开) */
    .bloodline-info {
      display: flex;
      justify-content: space-between;
      font-size: 0.95rem;
      color: $accent-gold;
      margin-top: 8px;
      padding: 6px 8px;
      border-radius: 4px;
      transition: all 0.2s;

      &.has-details {
        cursor: pointer;
        background: rgba(234, 179, 8, 0.05);
        border: 1px solid rgba(234, 179, 8, 0.2);

        &:hover {
          background: rgba(234, 179, 8, 0.1);
          box-shadow: $glow-shadow;
        }
      }

      .bloodline-name {
        font-weight: 500;
      }

      .bloodline-level {
        font-family: monospace;
      }
    }
  }
}

/* 血统详细信息悬浮弹窗 */
.bloodline-popover {
  background: #111116;
  border: 1px solid $border-gold;
  border-radius: 6px;
  padding: 12px;
  margin-bottom: 16px;
  box-shadow: 0 4px 20px rgba(0,0,0,0.8), $glow-shadow;

  .pop-title {
    margin: 0 0 8px 0;
    color: #fff;
    font-size: 1rem;
    border-bottom: 1px dotted rgba(234, 179, 8, 0.3);
    padding-bottom: 4px;

    .pop-level {
      color: $accent-gold;
      font-size: 0.85rem;
      font-weight: normal;
    }
  }

  .pop-desc {
    font-size: 0.85rem;
    color: $text-dim;
    margin-bottom: 12px;
    line-height: 1.4;
  }

  .pop-section {
    margin-bottom: 8px;

    .pop-subtitle {
      font-size: 0.8rem;
      color: $accent-gold;
      margin-bottom: 4px;
    }

    .pop-attr-grid {
      display: flex;
      flex-wrap: wrap;
      gap: 6px;

      .pop-attr-tag {
        background: rgba(255,255,255,0.05);
        border: 1px solid rgba(255,255,255,0.1);
        padding: 2px 6px;
        border-radius: 4px;
        font-size: 0.75rem;
        color: #fff;
      }
    }

    .pop-trait-list {
      margin: 0;
      padding-left: 16px;
      font-size: 0.8rem;
      color: $text-main;

      li {
        margin-bottom: 4px;
        strong { color: #fff; }
      }
    }
  }
}

.fade-enter-active, .fade-leave-active {
  transition: opacity 0.3s, transform 0.3s;
}
.fade-enter-from, .fade-leave-to {
  opacity: 0;
  transform: translateY(-10px);
}

/* 列表行统一样式 (黑魂属性列表风格) */
.list-row {
  display: flex;
  justify-content: space-between;
  padding: 4px 0;
  font-size: 0.95rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);

  .label { color: $text-dim; }
  .value { color: #fff; font-family: monospace; }

  /* 传奇属性专属特效 */
  .legendary-bonus {
    color: $accent-gold;
    text-shadow: 0 0 8px rgba(255, 255, 255, 0.8);
    font-weight: bold;
    margin-left: 2px;
  }
}

/* 资产区 */
.assets-section {
  margin-bottom: 24px;
}

.horizontal-assets {
  display: flex;
  justify-content: space-between;
  background: rgba(0, 0, 0, 0.3);
  padding: 8px 12px;
  border-radius: 4px;
  border: 1px solid rgba(255, 255, 255, 0.05);

  .h-asset {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;

    .label {
      font-size: 0.8rem;
      color: $text-dim;
    }
    .value {
      font-size: 1rem;
      color: $accent-gold;
      font-family: monospace;
      font-weight: bold;
    }
  }
}

/* 状态监控渐变条 */
.monitor-section {
  margin-bottom: 20px;

  .resource-row {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 8px;

    .res-label { width: 30px; font-size: 0.85rem; color: $text-dim; text-align: right; }
    .res-text { width: 80px; text-align: right; font-family: monospace; font-size: 0.85rem; color: #fff; }

    .res-bar-container {
      flex: 1;
      height: 6px;
      background: #1a1a24;
      border: 1px solid rgba(255,255,255,0.1);

      .res-bar {
        height: 100%;
        display: flex;

        .segment { height: 100%; transition: width 0.4s ease; }
      }

      &.hp-container .intact { background: #22c55e; }
      &.hp-container .shock { background: #eab308; }
      &.hp-container .lethal { background: #f97316; }
      &.hp-container .aggra { background: #ef4444; }

      &.wp-container .wp-fill { background: linear-gradient(90deg, #3b82f6, #60a5fa); box-shadow: 0 0 8px rgba(59,130,246,0.4); }
      &.ep-container .ep-fill { background: linear-gradient(90deg, #a855f7, #d946ef); box-shadow: 0 0 8px rgba(168,85,247,0.4); }
    }
  }
}

.derived-section {
  margin-bottom: 24px;
}

/* 技能滚动区 */
.skills-section {
  flex: 1;
  display: flex;
  flex-direction: column;

  .skills-scroll-area {
    flex: 1;
    max-height: 180px;
    overflow-y: auto;
    padding-right: 8px;

    &::-webkit-scrollbar { width: 4px; }
    &::-webkit-scrollbar-track { background: rgba(0,0,0,0.2); }
    &::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.2); border-radius: 2px; }
    &::-webkit-scrollbar-thumb:hover { background: $accent-gold; }

    .empty-hint {
      color: rgba(255,255,255,0.2);
      text-align: center;
      padding: 20px 0;
      font-style: italic;
      font-size: 0.85rem;
    }
  }
}

/* 响应式断点：当特别窄时转为单列 */
@media (max-width: 600px) {
  .panel-layout {
    flex-direction: column;
    gap: 20px;
  }
}
